#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> x={0.2,0.4,0.35,0.5,0.42};
double numerator=0,denominator=0;
for(int t=1;t<int(x.size());t++){
    numerator+=x[t]*x[t-1];
    denominator+=x[t-1]*x[t-1];
}
double A=numerator/denominator;
double variance=0;
for(int t=1;t<int(x.size());t++)variance+=pow(x[t]-A*x[t-1],2);
variance/=(x.size()-1);
cout<<"complete-state M-step A "<<A<<" Q "<<variance<<"\n";
return 0;
}

