#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> x={0,1,2,8,9};
double currentCenter=0,total=0;
vector<double> distances;
for(double value:x){
    double squared=pow(value-currentCenter,2);
    distances.push_back(squared);total+=squared;
}
double fixedUniform=0.6,threshold=fixedUniform*total,partial=0;
int selected=0;
for(int i=0;i<int(x.size());i++){
    partial+=distances[i];
    if(partial>=threshold){selected=i;break;}
}
cout<<"next center "<<x[selected]<<" draw probability "
    <<distances[selected]/total<<"\n";
return 0;
}

